// Назви задач, які треба пропускати (summary незмінний)
const SKIP_SUMMARIES = new Set([
  "Infrastructure",
  "BackOffice",
  "CustomerCare",
  "ProjectA",
  "Wellness",
  "TeamF",
  "Studio A",
  "TEAM-10",
  "Data Engineers",
  "Billing",
  "PROJECTE",
]);

// Повертає URL перегляду задачі за посиланням self та ключем
function getBrowseUrl(issue) {
  const selfUrl = issue?.self || issue?.json?.self;
  const key = issue?.key || issue?.json?.key;
  if (!selfUrl || !key) return "";
  const base = selfUrl.split("/rest/api/")[0];
  return `${base}/browse/${key}`;
}

// Конвертує Atlassian Document Format (ADF) у plain text
function adfToText(node) {
  if (!node) return "";
  if (typeof node === "string") return node;
  const out = [];
  const walk = (n) => {
    if (!n) return;
    if (typeof n === "string") {
      out.push(n);
      return;
    }
    if (n.type === "text" && typeof n.text === "string") {
      out.push(n.text);
      return;
    }
    // додаємо перенос рядка для деяких блоків
    if (["paragraph", "heading", "blockquote", "listItem"].includes(n.type)) {
      if (out.length && out[out.length - 1] !== "\n") out.push("\n");
    }
    if (Array.isArray(n.content)) n.content.forEach(walk);
    if (["paragraph", "heading", "blockquote", "listItem"].includes(n.type)) {
      out.push("\n");
    }
  };
  walk(node);
  return out.join("").replace(/\n{3,}/g, "\n\n").trim();
}

// Перетворює секунди у години (1 знакове після коми)
function secondsToHuman(seconds) {
  if (!seconds || typeof seconds !== "number") return "";
  const hours = seconds / 3600;
  const s = (Math.round(hours * 10) / 10).toString();
  return `${s}h`;
}

// Отримуємо всі вхідні items
const inputItems = $input.all();
const issues = inputItems.map((it) => it.json ?? it);

const parsed = [];

for (const issue of issues) {
  const key = issue.key || "";
  const fields = issue.fields || {};
  const rendered = issue.renderedFields || {};

  const summary = fields.summary || "";

  // Пропускаємо задачі зі списку
  if (SKIP_SUMMARIES.has(summary)) continue;

  // ----- Опис -----
  let description = "";
  // Якщо є HTML‑опис (renderedFields.description), використовуємо його як plain text
  if (typeof rendered.description === "string" && rendered.description.trim()) {
    description = rendered.description;
  }
  // Інакше беремо fields.description (ADF чи рядок)
  else if (fields.description) {
    if (typeof fields.description === "string") description = fields.description;
    else description = adfToText(fields.description);
  }

  // ----- Коментарі -----
  let commentsText = "";
  // Основне джерело: fields.comment.comments (масив)
  let commentsArray = Array.isArray(fields?.comment?.comments)
    ? fields.comment.comments
    : null;
  // fallback: fields.comments (у деяких конфігураціях може бути тут)
  if (!commentsArray && Array.isArray(fields.comments)) {
    commentsArray = fields.comments;
  }
  if (commentsArray && commentsArray.length) {
    const formatted = commentsArray.map((c) => {
      const author =
        c?.author?.displayName ||
        c?.updateAuthor?.displayName ||
        "Unknown";
      const created = c?.created ? ` (${c.created})` : "";
      // body може бути string або ADF
      let body = "";
      if (typeof c.body === "string") body = c.body;
      else if (c.body) body = adfToText(c.body);
      return `- ${author}${created}: ${body}`.trim();
    });
    commentsText = formatted.join("\n");
  }

  // ----- Дата дедлайну -----
  const dueDate = fields.duedate || "";

  // ----- Естімейт -----
  let estimate = "";
  const estSeconds =
    fields?.timetracking?.originalEstimateSeconds ??
    fields?.timeoriginalestimate ??
    null;
  if (typeof estSeconds === "number") {
    estimate = secondsToHuman(estSeconds);
  } else if (fields?.customfield_10016 != null) {
    // fallback (наприклад, story points)
    estimate = String(fields.customfield_10016);
  }

  // ----- Пріоритет -----
  let priority = "";
  if (fields?.priority) {
    // fields.priority може бути об'єктом { name: "High", id: "1", ... }
    if (typeof fields.priority === "string") {
      priority = fields.priority;
    } else {
      priority = fields.priority.name || fields.priority.id || "";
    }
  } else if (rendered.priority) {
    // у renderedFields.priority інколи є HTML‑рядок
    priority =
      typeof rendered.priority === "string"
        ? rendered.priority
        : rendered.priority?.name || "";
  }

  parsed.push({
    key,
    url: getBrowseUrl(issue),
    title: summary,
    description: description || "",
    comments: commentsText || "",
    dueDate,
    estimate,
    priority,
  });
}

// Збираємо дані у вигляді тексту для AI‑ноди
const text = parsed
  .map((t) => {
    return [
      `Ключ задачі: ${t.key}`,
      `Посилання: ${t.url}`,
      `Назва: ${t.title}`,
      `Опис: ${t.description || "-"}`,
      `Коментарі: ${t.comments ? `\n${t.comments}` : "-"}`,
      `Дата до якого потрібно виконати: ${t.dueDate || "-"}`,
      `Естімейт: ${t.estimate || "-"}`,
      `Пріоритет: ${t.priority || "-"}`,
      `---`,
    ].join("\n");
  })
  .join("\n");

// Повертаємо один item із масивом задач, текстом та кількістю
return [
  {
    json: {
      tasks: parsed,
      text,
      count: parsed.length,
    },
  },
];

const items = $input.all();

// 1) Дістаємо текст з найпоширеніших полів AI-ноди
function pickText(obj) {
  const candidates = [
    obj.text,
    obj.message,
    obj.answer,
    obj.result,
    obj.output,
    obj.content,
    obj.analysis,
  ];

  for (const c of candidates) {
    if (typeof c === "string" && c.trim()) return c;
  }

  // fallback: часто буває вкладено типу { data: { ... } } або масив
  // якщо нічого не знайшли — повернемо весь json (щоб хоч щось було)
  return JSON.stringify(obj, null, 2);
}

const rawText = items
  .map((it) => pickText(it.json ?? it))
  .filter(Boolean)
  .join("\n\n");

// 2) Нормалізація переносу рядків
const normalized = rawText.replace(/\r\n/g, "\n").replace(/\r/g, "\n").trim();

// 3) Масив рядків по \n + чистка
const lines = normalized
  .split("\n")
  .map((l) => l.trimEnd())
  .filter((l) => l.trim() !== "");

// 4) Секції (блоки) — розділення за порожнім рядком
const sections = normalized
  .split(/\n\s*\n/g)
  .map((s) => s.trim())
  .filter(Boolean);

return [
  {
    json: {
      text: normalized,
      lines,
      sections,
      lineCount: lines.length,
      sectionCount: sections.length,
    },
  },
];
